class Solution {
    public boolean containsNearbyDuplicate(int[] nums,int k){
        Map<Integer,Integer> last=new HashMap<>();
        for(int i=0;i<nums.length;i++){
            Integer previous=last.put(nums[i],i);
            if(previous!=null&&i-previous<=k)return true;
        }
        return false;
    }
}

code.kotlin:
class Solution {
    fun containsNearbyDuplicate(nums:IntArray,k:Int):Boolean{
        val last=hashMapOf<Int,Int>();
        for(i in nums.indices){
            val previous=last.put(nums[i],i);
            if(previous!=null&&i-previous<=k)return true
        };
        return false
    }
}

code.cpp:
class Solution {
    public: bool containsNearbyDuplicate(vector<int>& nums,int k){
        unordered_map<int,int> last;
        for(int i=0;i<(int)nums.size();++i){
            auto it=last.find(nums[i]);
            if(it!=last.end()&&i-it->second<=k)return true;
            last[nums[i]]=i;
        }
        return false;
    }
};
